INSERT INTO `cache` VALUES ('payroll-lim-cache-app_setting.app_logo','s:53:\"branding/KvGPUbt5CBIpmO7iPXALitBk520ha8kp0p07bGYB.png\";',2096088932),('payroll-lim-cache-app_setting.app_name','s:14:\"LIM Management\";',2096088932),('payroll-lim-cache-app_setting.app_tagline','s:22:\"Management Application\";',2096088932),('payroll-lim-cache-app_setting.contract_template_bank_account','s:10:\"1234567890\";',2096088786),('payroll-lim-cache-app_setting.contract_template_bank_account_name','s:13:\"Daniel Kawalo\";',2096088786),('payroll-lim-cache-app_setting.contract_template_bank_name','s:3:\"BCA\";',2096088786),('payroll-lim-cache-app_setting.contract_template_contract_value','s:7:\"8000000\";',2096088786),('payroll-lim-cache-app_setting.contract_template_contract_value_text','s:19:\"Delapan Juta Rupiah\";',2096088786),('payroll-lim-cache-app_setting.contract_template_dispute_terms','s:153:\"Perselisihan diselesaikan melalui musyawarah mufakat terlebih dahulu; jika tidak tercapai, PARA PIHAK menempuh jalur hukum sesuai peraturan yang berlaku.\";',2096088786),('payroll-lim-cache-app_setting.contract_template_duration_text','s:7:\"4 bulan\";',2096088786),('payroll-lim-cache-app_setting.contract_template_first_party_address','s:66:\"Jalan Wijaya Kusuma No.37, Sinduadi, Mlati, Sleman, DI Yogyakarta.\";',2096088786),('payroll-lim-cache-app_setting.contract_template_first_party_company','s:53:\"Perkumpulan Masyarakat Antifitnah Indonesia (Mafindo)\";',2096088786),('payroll-lim-cache-app_setting.contract_template_first_party_name','s:20:\"Septiaji Eko Nugroho\";',2096088786),('payroll-lim-cache-app_setting.contract_template_first_party_position','s:15:\"Ketua Presidium\";',2096088786),('payroll-lim-cache-app_setting.contract_template_hki_terms','s:138:\"Hasil pekerjaan yang dibuat PIHAK KEDUA dalam penugasan ini digunakan untuk kepentingan PIHAK KESATU sesuai ketentuan internal organisasi.\";',2096088786),('payroll-lim-cache-app_setting.contract_template_location','s:10:\"Yogyakarta\";',2096088786),('payroll-lim-cache-app_setting.contract_template_nda_terms','s:167:\"PIHAK KEDUA memberikan persetujuan kepada PIHAK KESATU untuk mengumpulkan, memproses, menyimpan, dan menjaga data pribadi PIHAK KEDUA sepanjang terkait hubungan kerja.\";',2096088786),('payroll-lim-cache-app_setting.contract_template_notes','s:227:\"Pasal 9 (Lain-lain): ketentuan yang bertentangan dengan peraturan akan direvisi sesuai kesepakatan PARA PIHAK.\nPasal 10 (Penutup): perjanjian ditandatangani sadar tanpa paksaan, rangkap 2, dan memiliki kekuatan hukum yang sama.\";',2096088786),('payroll-lim-cache-app_setting.contract_template_payment_method','s:14:\"Honor Bertahap\";',2096088786),('payroll-lim-cache-app_setting.contract_template_payment_terms','s:221:\"Honor ke-1: Rp 4.000.000, potongan PPh 2,5% Rp 100.000, diterima Rp 3.900.000.\nHonor ke-2: Rp 4.000.000, potongan PPh 2,5% Rp 100.000, diterima Rp 3.900.000.\nTotal PPh: Rp 200.000 sesuai ketentuan perpajakan yang berlaku.\";',2096088786),('payroll-lim-cache-app_setting.contract_template_project_name','s:37:\"Pekerja Lepas - Web Developer Mafindo\";',2096088786),('payroll-lim-cache-app_setting.contract_template_rights_obligations','s:365:\"Hak PIHAK KESATU: memberikan pekerjaan sesuai kualifikasi dan meninjau kinerja PIHAK KEDUA.\nKewajiban PIHAK KESATU: membayar kompensasi sesuai kesepakatan.\nHak PIHAK KEDUA: menerima upah/honor setelah menjalankan kewajiban.\nKewajiban PIHAK KEDUA: menjaga etika, loyalitas, mematuhi aturan internal, menjaga aset, dan mengembalikan data saat hubungan kerja berakhir.\";',2096088786),('payroll-lim-cache-app_setting.contract_template_sanctions_terms','s:259:\"Perintah kerja berakhir saat masa kontrak selesai.\nPemutusan tanpa syarat dapat terjadi karena alasan mendesak (penipuan, penggelapan, pelanggaran berat, atau pelanggaran pidana).\nPengunduran diri PIHAK KEDUA wajib disampaikan minimal 30 hari sebelum efektif.\";',2096088786),('payroll-lim-cache-app_setting.contract_template_scope_of_work','s:315:\"1. Melakukan pemeliharaan website mafindo.or.id agar berjalan lancar dan nyaman diakses pengguna.\n2. Memastikan website dapat diakses baik melalui desktop, tablet, maupun ponsel.\n3. Melakukan pelatihan kepada tim pengelola website.\n4. Mematuhi perubahan tugas dari PIHAK KESATU sepanjang berkaitan dengan pekerjaan.\";',2096088786),('payroll-lim-cache-app_setting.contract_template_second_party_address','s:80:\"Lingk Rengas, RT/RW 001/006, Tambakboyo, Kecamatan Ambarawa, Kabupaten Semarang.\";',2096088786),('payroll-lim-cache-app_setting.contract_template_second_party_ktp','s:16:\"3322102304960003\";',2096088786),('payroll-lim-cache-app_setting.contract_template_second_party_name','s:13:\"Daniel Kawalo\";',2096088786);
