INSERT INTO `contract_documents` VALUES (1,2,1,'234/SPK/LIM/06/2026','2026-06-06','Jakarta','Nama Penanggung Jawab','Direktur Utama','PT Lingkar Inovasi Muda','Alamat perusahaan pihak pertama.','Nama Lengkap Freelancer/Penyedia Jasa','Alamat lengkap pihak kedua.','Nomor KTP','Pengembangan Aplikasi Mobile','1. Pembuatan modul QR Scanner dan Generator.\r\n2. Integrasi sistem manajemen pengguna (User Management).\r\n3. Penyerahan source code dan dokumentasi teknis.','6 bulan','2026-06-06','2026-12-06',50000000.00,'Lima Puluh Juta Rupiah','Lump Sum','Termin I (Uang Muka): 30% setelah penandatanganan kontrak.\r\nTermin II (Progress): 50% setelah aplikasi versi Beta selesai diuji coba.\r\nTermin III (Pelunasan): 20% setelah pekerjaan selesai 100% dan BAST diterbitkan.','Hak Pihak Pertama: menerima hasil pekerjaan sesuai spesifikasi dan ketepatan waktu.\r\nKewajiban Pihak Pertama: menyediakan data/informasi dan melakukan pembayaran sesuai termin.\r\nHak Pihak Kedua: menerima pembayaran tepat waktu dan dokumen pendukung yang jelas.\r\nKewajiban Pihak Kedua: menyelesaikan pekerjaan secara profesional sesuai jadwal.','Seluruh hasil karya, source code, desain, dokumen, dan material yang dihasilkan menjadi milik PIHAK PERTAMA setelah pelunasan pembayaran dilakukan.','PIHAK KEDUA wajib menjaga kerahasiaan seluruh data, informasi, dokumen, dan strategi bisnis PIHAK PERTAMA selama masa kontrak maupun setelahnya.','Apabila PIHAK KEDUA terlambat menyelesaikan pekerjaan, dikenakan denda 0,1% per hari dari sisa nilai kontrak, maksimal 5%.','Perselisihan diselesaikan terlebih dahulu secara musyawarah. Jika tidak tercapai mufakat, diselesaikan melalui Pengadilan Negeri Jakarta Selatan.','BCA','1234567890','Nama Pihak Kedua',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Template otomatis. Silakan sesuaikan detail para pihak, angka termin, dan klausul sebelum disimpan.','2026-06-05 23:30:07','2026-06-05 23:30:07'),(2,3,1,'235/SPK/LIM/06/2026','2026-06-06','Jakarta','Nama Penanggung Jawab','Direktur Utama','PT Lingkar Inovasi Muda','Alamat perusahaan pihak pertama.','Nama Lengkap Freelancer/Penyedia Jasa','Alamat lengkap pihak kedua.','Nomor KTP','Pengembangan Aplikasi Mobile','1. Pembuatan modul QR Scanner dan Generator.\r\n2. Integrasi sistem manajemen pengguna (User Management).\r\n3. Penyerahan source code dan dokumentasi teknis.','2 bulan','2026-06-06','2026-08-06',50000000.00,'Lima Puluh Juta Rupiah','Lump Sum','Termin I (Uang Muka): 30% setelah penandatanganan kontrak.\r\nTermin II (Progress): 50% setelah aplikasi versi Beta selesai diuji coba.\r\nTermin III (Pelunasan): 20% setelah pekerjaan selesai 100% dan BAST diterbitkan.','Hak Pihak Pertama: menerima hasil pekerjaan sesuai spesifikasi dan ketepatan waktu.\r\nKewajiban Pihak Pertama: menyediakan data/informasi dan melakukan pembayaran sesuai termin.\r\nHak Pihak Kedua: menerima pembayaran tepat waktu dan dokumen pendukung yang jelas.\r\nKewajiban Pihak Kedua: menyelesaikan pekerjaan secara profesional sesuai jadwal.','Seluruh hasil karya, source code, desain, dokumen, dan material yang dihasilkan menjadi milik PIHAK PERTAMA setelah pelunasan pembayaran dilakukan.','PIHAK KEDUA wajib menjaga kerahasiaan seluruh data, informasi, dokumen, dan strategi bisnis PIHAK PERTAMA selama masa kontrak maupun setelahnya.','Apabila PIHAK KEDUA terlambat menyelesaikan pekerjaan, dikenakan denda 0,1% per hari dari sisa nilai kontrak, maksimal 5%.','Perselisihan diselesaikan terlebih dahulu secara musyawarah. Jika tidak tercapai mufakat, diselesaikan melalui Pengadilan Negeri Jakarta Selatan.','BCA','1234567890','Nama Pihak Kedua',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Template otomatis. Silakan sesuaikan detail para pihak, angka termin, dan klausul sebelum disimpan.','2026-06-05 23:31:04','2026-06-05 23:31:04'),(3,4,1,'236/SPK/LIM/06/2026','2026-06-06','Jakarta','Nama Penanggung Jawab','Direktur Utama','PT Lingkar Inovasi Muda','Alamat perusahaan pihak pertama.','Nama Lengkap Freelancer/Penyedia Jasa','Alamat lengkap pihak kedua.','Nomor KTP','Pengembangan Aplikasi Mobile','1. Pembuatan modul QR Scanner dan Generator.\r\n2. Integrasi sistem manajemen pengguna (User Management).\r\n3. Penyerahan source code dan dokumentasi teknis.','1 tahun','2026-06-06','2027-06-06',50000000.00,'Lima Puluh Juta Rupiah','Lump Sum','Termin I (Uang Muka): 30% setelah penandatanganan kontrak.\r\nTermin II (Progress): 50% setelah aplikasi versi Beta selesai diuji coba.\r\nTermin III (Pelunasan): 20% setelah pekerjaan selesai 100% dan BAST diterbitkan.','Hak Pihak Pertama: menerima hasil pekerjaan sesuai spesifikasi dan ketepatan waktu.\r\nKewajiban Pihak Pertama: menyediakan data/informasi dan melakukan pembayaran sesuai termin.\r\nHak Pihak Kedua: menerima pembayaran tepat waktu dan dokumen pendukung yang jelas.\r\nKewajiban Pihak Kedua: menyelesaikan pekerjaan secara profesional sesuai jadwal.','Seluruh hasil karya, source code, desain, dokumen, dan material yang dihasilkan menjadi milik PIHAK PERTAMA setelah pelunasan pembayaran dilakukan.','PIHAK KEDUA wajib menjaga kerahasiaan seluruh data, informasi, dokumen, dan strategi bisnis PIHAK PERTAMA selama masa kontrak maupun setelahnya.','Apabila PIHAK KEDUA terlambat menyelesaikan pekerjaan, dikenakan denda 0,1% per hari dari sisa nilai kontrak, maksimal 5%.','Perselisihan diselesaikan terlebih dahulu secara musyawarah. Jika tidak tercapai mufakat, diselesaikan melalui Pengadilan Negeri Jakarta Selatan.','BCA','1234567890','Nama Pihak Kedua',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Template otomatis. Silakan sesuaikan detail para pihak, angka termin, dan klausul sebelum disimpan.','2026-06-05 23:31:37','2026-06-06 00:52:58'),(4,3,1,'237/SPK/LIM/06/2026','2026-06-06','Yogyakarta','Septiaji Eko Nugroho','Ketua Presidium','Perkumpulan Masyarakat Antifitnah Indonesia (Mafindo)','Jalan Wijaya Kusuma No.37, Sinduadi, Mlati, Sleman, DI Yogyakarta.','Daniel Kawalo','Lingk Rengas, RT/RW 001/006, Tambakboyo, Kecamatan Ambarawa, Kabupaten Semarang.','3322102304960003','Pekerja Lepas - Web Developer Mafindo','1. Melakukan pemeliharaan website mafindo.or.id agar berjalan lancar dan nyaman diakses pengguna.\r\n2. Memastikan website dapat diakses baik melalui desktop, tablet, maupun ponsel.\r\n3. Melakukan pelatihan kepada tim pengelola website.\r\n4. Mematuhi perubahan tugas dari PIHAK KESATU sepanjang berkaitan dengan pekerjaan.','4 bulan','2026-06-06','2026-10-06',8000000.00,'Delapan Juta Rupiah','Honor Bertahap','Honor ke-1: Rp 4.000.000, potongan PPh 2,5% Rp 100.000, diterima Rp 3.900.000.\r\nHonor ke-2: Rp 4.000.000, potongan PPh 2,5% Rp 100.000, diterima Rp 3.900.000.\r\nTotal PPh: Rp 200.000 sesuai ketentuan perpajakan yang berlaku.','Hak PIHAK KESATU: memberikan pekerjaan sesuai kualifikasi dan meninjau kinerja PIHAK KEDUA.\r\nKewajiban PIHAK KESATU: membayar kompensasi sesuai kesepakatan.\r\nHak PIHAK KEDUA: menerima upah/honor setelah menjalankan kewajiban.\r\nKewajiban PIHAK KEDUA: menjaga etika, loyalitas, mematuhi aturan internal, menjaga aset, dan mengembalikan data saat hubungan kerja berakhir.','Hasil pekerjaan yang dibuat PIHAK KEDUA dalam penugasan ini digunakan untuk kepentingan PIHAK KESATU sesuai ketentuan internal organisasi.','PIHAK KEDUA memberikan persetujuan kepada PIHAK KESATU untuk mengumpulkan, memproses, menyimpan, dan menjaga data pribadi PIHAK KEDUA sepanjang terkait hubungan kerja.','Perintah kerja berakhir saat masa kontrak selesai.\r\nPemutusan tanpa syarat dapat terjadi karena alasan mendesak (penipuan, penggelapan, pelanggaran berat, atau pelanggaran pidana).\r\nPengunduran diri PIHAK KEDUA wajib disampaikan minimal 30 hari sebelum efektif.','Perselisihan diselesaikan melalui musyawarah mufakat terlebih dahulu; jika tidak tercapai, PARA PIHAK menempuh jalur hukum sesuai peraturan yang berlaku.','BCA','1234567890','Daniel Kawalo',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Pasal 9 (Lain-lain): ketentuan yang bertentangan dengan peraturan akan direvisi sesuai kesepakatan PARA PIHAK.\r\nPasal 10 (Penutup): perjanjian ditandatangani sadar tanpa paksaan, rangkap 2, dan memiliki kekuatan hukum yang sama.','2026-06-05 23:41:38','2026-06-05 23:47:13');
